import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"支付寶帳單匯入教學","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/03-alipay-bill-import-guide.md","filePath":"v1/zh-HK/guide/03-alipay-bill-import-guide.md"}'),r={name:"v1/zh-HK/guide/03-alipay-bill-import-guide.md"};function e(d,l,n,h,s,u){return a(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="支付寶帳單匯入教學" tabindex="-1">支付寶帳單匯入教學 <a class="header-anchor" href="#支付寶帳單匯入教學" aria-label="Permalink to &quot;支付寶帳單匯入教學&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>本教學將指引你如何從支付寶匯出帳單，並匯入到考拉記帳 App。</p><hr><h2 id="📱-第一步-在支付寶中匯出帳單" tabindex="-1">📱 第一步：在支付寶中匯出帳單 <a class="header-anchor" href="#📱-第一步-在支付寶中匯出帳單" aria-label="Permalink to &quot;📱 第一步：在支付寶中匯出帳單&quot;">​</a></h2><h3 id="步驟-1-打開支付寶帳單頁面" tabindex="-1">步驟 1：打開支付寶帳單頁面 <a class="header-anchor" href="#步驟-1-打開支付寶帳單頁面" aria-label="Permalink to &quot;步驟 1：打開支付寶帳單頁面&quot;">​</a></h3><ol><li>打開支付寶 App</li><li>點擊底部導覽列的 <strong>「我的」</strong></li><li>點擊 <strong>「帳單」</strong> 進入帳單頁</li></ol><blockquote><p>📝 <strong>注意</strong>：不同版本的支付寶入口可能略有不同。若找不到，可在支付寶搜尋框搜尋「帳單」。</p></blockquote><h3 id="步驟-2-匯出帳單" tabindex="-1">步驟 2：匯出帳單 <a class="header-anchor" href="#步驟-2-匯出帳單" aria-label="Permalink to &quot;步驟 2：匯出帳單&quot;">​</a></h3><ol><li>在帳單頁點擊右上角 <strong>「...」</strong></li><li>選擇 <strong>「开具交易流水证明」</strong> 或 <strong>「账单导出」</strong></li><li>選擇 <strong>「用户个人对帐」</strong>，並點擊 <strong>「申请」</strong></li></ol><h3 id="步驟-3-選擇交易範圍" tabindex="-1">步驟 3：選擇交易範圍 <a class="header-anchor" href="#步驟-3-選擇交易範圍" aria-label="Permalink to &quot;步驟 3：選擇交易範圍&quot;">​</a></h3><ol><li>選擇交易類型：<strong>全部交易</strong> / <strong>收入</strong> / <strong>支出</strong></li><li>選擇匯出時間範圍（例如：最近一個月、最近三個月）</li><li>選擇接收方式：<strong>支付宝</strong> / <strong>邮箱</strong></li></ol><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>建議一次匯出不超過 3 個月，避免檔案過大</li><li>若需匯出更長時間，可分多次匯出</li><li>若選擇郵箱接收，支付寶會透過郵件發送帳單檔案（需先設定郵箱）</li></ul></blockquote><h3 id="步驟-4-把檔案保存到裝置" tabindex="-1">步驟 4：把檔案保存到裝置 <a class="header-anchor" href="#步驟-4-把檔案保存到裝置" aria-label="Permalink to &quot;步驟 4：把檔案保存到裝置&quot;">​</a></h3><ol><li>若選擇郵件： <ul><li>打開郵箱，找到支付寶發送的郵件</li><li>下載附件（CSV）</li><li>保存到裝置本機（檔案管理器可存取的位置）</li></ul></li><li>若選擇「保存到檔案」（如支援）： <ul><li>檔案會保存到下載資料夾</li><li>記住保存位置</li></ul></li></ol><blockquote><p>📝 <strong>檔案位置提示</strong>：</p><ul><li>iOS：通常在「檔案」App 的「下載」資料夾</li><li>Android：通常在「下載」資料夾或「支付寶」資料夾</li></ul></blockquote><hr><h2 id="📱-第二步-在考拉記帳中匯入" tabindex="-1">📱 第二步：在考拉記帳中匯入 <a class="header-anchor" href="#📱-第二步-在考拉記帳中匯入" aria-label="Permalink to &quot;📱 第二步：在考拉記帳中匯入&quot;">​</a></h2><h3 id="步驟-1-進入匯入頁面" tabindex="-1">步驟 1：進入匯入頁面 <a class="header-anchor" href="#步驟-1-進入匯入頁面" aria-label="Permalink to &quot;步驟 1：進入匯入頁面&quot;">​</a></h3><ol><li>打開考拉記帳 App</li><li>點擊底部導覽列的 <strong>「設定」</strong></li><li>在設定頁面中找到 <strong>「帳單匯入」</strong></li><li>點擊進入帳單匯入頁</li></ol><h3 id="步驟-2-選擇匯入來源" tabindex="-1">步驟 2：選擇匯入來源 <a class="header-anchor" href="#步驟-2-選擇匯入來源" aria-label="Permalink to &quot;步驟 2：選擇匯入來源&quot;">​</a></h3><ol><li>點擊 <strong>「匯入來源」</strong></li><li>在列表中選擇 <strong>「支付寶」</strong></li><li>確認選擇</li></ol><blockquote><p>⚠️ <strong>重要</strong>：必須選擇「支付寶」，否則系統無法正確解析檔案格式。</p></blockquote><h3 id="步驟-3-選擇檔案" tabindex="-1">步驟 3：選擇檔案 <a class="header-anchor" href="#步驟-3-選擇檔案" aria-label="Permalink to &quot;步驟 3：選擇檔案&quot;">​</a></h3><ol><li>點擊 <strong>「檔案路徑」</strong></li><li>在檔案選擇器中找到並選擇支付寶匯出的帳單檔</li><li>確認已選擇檔案（會顯示檔名）</li></ol><blockquote><p>📝 <strong>檔案格式</strong>：</p><ul><li>僅支援 CSV（<code>.csv</code>）</li><li>檔名通常包含「支付寶」或「Alipay」</li></ul></blockquote><h3 id="步驟-4-關聯帳本" tabindex="-1">步驟 4：關聯帳本 <a class="header-anchor" href="#步驟-4-關聯帳本" aria-label="Permalink to &quot;步驟 4：關聯帳本&quot;">​</a></h3><ol><li>點擊 <strong>「關聯帳本」</strong></li><li>選擇匯入目標帳本</li><li>確認帳本選擇</li></ol><blockquote><p>💡 <strong>提示</strong>：若只有一個帳本，系統會自動關聯預設帳本。</p></blockquote><h3 id="步驟-5-解析檔案" tabindex="-1">步驟 5：解析檔案 <a class="header-anchor" href="#步驟-5-解析檔案" aria-label="Permalink to &quot;步驟 5：解析檔案&quot;">​</a></h3><ol><li>點擊右上角 <strong>「解析」</strong></li><li>等待解析（可能需要幾秒）</li><li>解析成功後會自動跳轉到預覽頁</li></ol><h3 id="步驟-6-預覽與編輯" tabindex="-1">步驟 6：預覽與編輯 <a class="header-anchor" href="#步驟-6-預覽與編輯" aria-label="Permalink to &quot;步驟 6：預覽與編輯&quot;">​</a></h3><p>預覽頁可：</p><ul><li>查看所有帳單（按日期分組）</li><li>編輯單筆（分類、金額、時間、帳戶、標籤、備註）</li><li>長按刪除無效記錄</li><li>批量跳過無效記錄</li></ul><h3 id="步驟-7-匯入資料" tabindex="-1">步驟 7：匯入資料 <a class="header-anchor" href="#步驟-7-匯入資料" aria-label="Permalink to &quot;步驟 7：匯入資料&quot;">​</a></h3><ol><li>在預覽頁確認資料無誤後</li><li>點擊 <strong>「匯入」</strong></li><li>等待匯入完成</li></ol><hr><h2 id="📋-支付寶帳單檔案格式說明-csv" tabindex="-1">📋 支付寶帳單檔案格式說明（CSV） <a class="header-anchor" href="#📋-支付寶帳單檔案格式說明-csv" aria-label="Permalink to &quot;📋 支付寶帳單檔案格式說明（CSV）&quot;">​</a></h2><p>支付寶匯出的 CSV 通常包含以下欄位：</p><table tabindex="0"><thead><tr><th>欄名</th><th>說明</th><th>示例</th></tr></thead><tbody><tr><td>交易時間</td><td>交易建立時間</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易分類</td><td>收支分類名稱</td><td>餐饮美食/日用百货</td></tr><tr><td>交易對方</td><td>交易對方資訊</td><td>張三 / 商戶名稱</td></tr><tr><td>對方帳號</td><td>對方支付寶帳號</td><td><a href="mailto:xxx@163.com" target="_blank" rel="noreferrer">xxx@163.com</a></td></tr><tr><td>商品說明</td><td>商品描述</td><td>午餐 / 購物等</td></tr><tr><td>收/支</td><td>收入或支出</td><td>收入 / 支出</td></tr><tr><td>金額</td><td>交易金額</td><td>100.00</td></tr><tr><td>收/付款方式</td><td>付款來源/方式</td><td>余额宝</td></tr><tr><td>交易狀態</td><td>交易狀態</td><td>交易成功 / 已退款</td></tr><tr><td>交易訂單號</td><td>交易單號</td><td>20240101...</td></tr><tr><td>商家訂單號</td><td>商家單號</td><td>1234567890</td></tr><tr><td>備註</td><td>備註資訊</td><td>備註內容</td></tr></tbody></table><blockquote><p>📝 <strong>注意</strong>：不同版本的支付寶欄名可能略有不同，但主要內容相同。</p></blockquote><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><h3 id="_1-檔案格式要求" tabindex="-1">1. 檔案格式要求 <a class="header-anchor" href="#_1-檔案格式要求" aria-label="Permalink to &quot;1. 檔案格式要求&quot;">​</a></h3><ul><li><strong>檔案編碼</strong>：建議 UTF-8（支付寶匯出可能為 UTF-8 或 GBK）</li><li><strong>檔案格式</strong>：僅支援 CSV（<code>.csv</code>）</li><li><strong>檔案大小</strong>：建議單檔不超過 10MB</li></ul><h3 id="_2-欄位映射-匯入行為" tabindex="-1">2. 欄位映射（匯入行為） <a class="header-anchor" href="#_2-欄位映射-匯入行為" aria-label="Permalink to &quot;2. 欄位映射（匯入行為）&quot;">​</a></h3><p>系統會把支付寶欄位映射到考拉記帳欄位（概念如下）：</p><ul><li>交易時間（row[0]）→ 帳單日期（只取日期，<code>yyyy-MM-dd</code>）</li><li>交易分類（row[1]）→ 父/子分類（父子同名）</li><li>收/支（row[5]）→ 帳單類型（收入/支出）</li><li>金額（row[6]）→ 帳單金額</li><li>收/付款方式（row[7]）→ 帳戶（按名稱匹配/建立）</li><li>交易對方、對方帳號、商品說明、交易狀態、訂單號等 → 會追加拼接到帳單備註</li><li>備註（row[11]）→ 原始備註（若為「/」或空會忽略，再疊加上述追加項）</li></ul><h3 id="_3-重複與退款" tabindex="-1">3. 重複與退款 <a class="header-anchor" href="#_3-重複與退款" aria-label="Permalink to &quot;3. 重複與退款&quot;">​</a></h3><ul><li>若匯入記錄與現有記錄重複（通常基於交易號），系統可能會自動跳過</li><li>若包含退款記錄，建議在預覽頁確認是否處理正確</li></ul><h3 id="_4-不要手動修改帳單檔" tabindex="-1">4. 不要手動修改帳單檔 <a class="header-anchor" href="#_4-不要手動修改帳單檔" aria-label="Permalink to &quot;4. 不要手動修改帳單檔&quot;">​</a></h3><p>不要手動修改支付寶帳單（包含但不限於修改/刪除表頭、或新增列），否則可能導致解析失敗。</p><hr><h2 id="🔧-常見問題" tabindex="-1">🔧 常見問題 <a class="header-anchor" href="#🔧-常見問題" aria-label="Permalink to &quot;🔧 常見問題&quot;">​</a></h2><h3 id="q1-找不到「匯出帳單」選項" tabindex="-1">Q1：找不到「匯出帳單」選項？ <a class="header-anchor" href="#q1-找不到「匯出帳單」選項" aria-label="Permalink to &quot;Q1：找不到「匯出帳單」選項？&quot;">​</a></h3><p>可能原因：</p><ol><li>支付寶版本較舊，不支援匯出</li><li>入口位置不同，可嘗試： <ul><li>在帳單頁點擊右上角「...」</li><li>在「我的」頁查找「帳單」</li><li>在支付寶搜尋框搜尋「帳單匯出」</li></ul></li></ol><h3 id="q2-匯出後收不到郵件" tabindex="-1">Q2：匯出後收不到郵件？ <a class="header-anchor" href="#q2-匯出後收不到郵件" aria-label="Permalink to &quot;Q2：匯出後收不到郵件？&quot;">​</a></h3><p>請檢查：</p><ol><li>支付寶是否已綁定郵箱</li><li>郵箱地址是否正確</li><li>郵件是否進入垃圾郵件</li><li>可改用「保存到檔案」方式</li></ol><h3 id="q3-解析失敗怎麼辦" tabindex="-1">Q3：解析失敗怎麼辦？ <a class="header-anchor" href="#q3-解析失敗怎麼辦" aria-label="Permalink to &quot;Q3：解析失敗怎麼辦？&quot;">​</a></h3><p>請檢查：</p><ol><li>檔案格式是否正確（CSV）</li><li>是否選擇「支付寶」作為匯入來源</li><li>檔案是否損壞</li><li>檔案編碼是否正確（建議 UTF-8 或 GBK）</li></ol><hr><h2 id="💡-使用技巧" tabindex="-1">💡 使用技巧 <a class="header-anchor" href="#💡-使用技巧" aria-label="Permalink to &quot;💡 使用技巧&quot;">​</a></h2><ol><li><strong>定期匯入</strong>：建議每月匯入一次，保持資料同步</li><li><strong>分類整理</strong>：匯入後檢查並整理分類，方便統計</li><li><strong>帳戶管理</strong>：先建立常用帳戶，避免自動建立不規範的帳戶名稱</li><li><strong>資料備份</strong>：匯入前建議先備份現有資料</li><li><strong>退款處理</strong>：匯入後建議檢查退款記錄是否正確</li></ol><hr><p><strong>最後更新</strong>：2026 年 5 月</p>',68)])])}const b=t(r,[["render",e]]);export{g as __pageData,b as default};
